import {getLanguage} from './locales/locale.mjs';
const t=(zh,en)=>getLanguage()==='en'?en:zh;
const money=(n,d=2)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:d}).format(n);

export function feeHistoryPanel(f){
  const period=f.start.slice(0,10)+' → '+f.end.slice(0,10);
  return `<section class="panel live-fee-panel"><details class="live-fee-method"><summary><span>${t('手续费明细与计算口径','Fee breakdown & calculation')}</span><small>${period}</small></summary><p class="live-fee-definition">${t('累计估值 = 期间领取记录 + 当前待领取 − 期初待领取','Cumulative value = recorded claims + current unclaimed − opening unclaimed')}</p><table><thead><tr><th>${t('项目','Item')}</th><th>Core LP</th><th>Active LP</th><th>${t('合计','Total')}</th></tr></thead><tbody>${[[t('期间领取记录','Recorded claims in period'),'recordedClaims'],[t('期末待领取','Ending unclaimed'),'unclaimedBalance'],[t('减：期初待领取','Less: opening unclaimed'),'openingBalance'],[t('期间累计手续费估值','Cumulative marked fee value'),'value']].map(([name,key])=>`<tr><td>${name}</td><td>${money(f.roles.core[key])}</td><td>${money(f.roles.active[key])}</td><td>${money(f.roles.core[key]+f.roles.active[key])}</td></tr>`).join('')}</tbody></table><p>${t('当前待领取已包含在累计费用估值与组合净值中，不再相加。','Current unclaimed fees are already included in cumulative fee value and portfolio NAV; do not add them again.')}</p><p>${t('来源：CIRCLE LP NAV 正式历史记录；空白费用项按 0 处理。不是将每天的待领取余额求和。','Source: the official CIRCLE LP NAV history. Blank fee entries are treated as zero. Daily unclaimed balances are never summed.')}</p><p>${t('这项统计包含价格重估，不能等同于剔除币价变化后的新增手续费收入，也不能直接换算为费用 APR。模拟中的 APR 仍使用原来单独标注的校准窗口。','This measure includes repricing, so it is not newly accrued fee income net of price effects and cannot be used directly as fee APR. Simulation APRs retain their separately labeled calibration window.')}</p><p>${t('历史领取已由持有人确认，并与监控表金额核对；未纳入监控的其他钱包费用不计入。','Historical claims were confirmed by the owner and reconciled to the monitoring workbook. Fees from other unmonitored wallets are excluded.')}</p><small>${t('来源版本 SHA-256','Source version SHA-256')}: <code>${f.source.sha256}</code></small></details></section>`;
}
